const metricTargets = ["vehicle_count", "route_count", "order_count", "trip_count"];

function setMetric(key, value) {
    const element = root_element.querySelector(`[data-metric="${key}"]`);
    if (element) {
        element.textContent = String(value ?? 0);
    }
}

function setDynamicLink(key, docname, fallbackRoute, docRoute) {
    const element = root_element.querySelector(`[data-dynamic-link="${key}"]`);
    if (!element) {
        return;
    }

    element.href = docname ? `${docRoute}/${encodeURIComponent(docname)}` : fallbackRoute;
}

frappe
    .call("trans_ms.transport_management.hazchem_operations.get_transport_workspace_snapshot")
    .then((response) => {
        const data = response.message || {};

        metricTargets.forEach((key) => setMetric(key, data[key]));
        setDynamicLink("order", data.latest_order, "/app/transportation-order/view/list", "/app/transportation-order");
        setDynamicLink("trip", data.latest_trip, "/app/vehicle-trip/view/list", "/app/vehicle-trip");
    })
    .catch(() => {
        // Keep the server-rendered fallback values when the live refresh is unavailable.
    });

style:
.tm-flow-shell {
    font-family: "Segoe UI", Arial, sans-serif;
    color: #122230;
    display: grid;
    gap: 18px;
}

.tm-flow-hero {
    display: grid;
    grid-template-columns: 2.3fr 1fr;
    gap: 16px;
    padding: 18px 20px;
    border-radius: 18px;
    background: linear-gradient(135deg, #eef6ff 0%, #f8fbff 60%, #fff5e6 100%);
    border: 1px solid #d9e6f2;
}

.tm-flow-kicker {
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 11px;
    font-weight: 700;
    color: #9a3412;
    margin-bottom: 8px;
}

.tm-flow-hero h2 {
    margin: 0 0 10px;
    font-size: 24px;
    line-height: 1.2;
}

.tm-flow-hero p {
    margin: 0;
    line-height: 1.6;
    color: #334155;
}

.tm-flow-note {
    margin-top: 12px !important;
    font-size: 13px;
}

.tm-flow-metrics {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    align-content: start;
}

.tm-flow-metrics div {
    background: rgba(255, 255, 255, 0.86);
    border: 1px solid #d6e3ef;
    border-radius: 14px;
    padding: 14px;
}

.tm-flow-metrics span {
    display: block;
    font-size: 24px;
    font-weight: 700;
    color: #0f4c81;
}

.tm-flow-metrics small {
    display: block;
    margin-top: 4px;
    color: #475569;
}

.tm-flow-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 14px;
}

.tm-step {
    padding: 16px;
    border-radius: 16px;
    border: 1px solid #d9e2ec;
    background: #ffffff;
    box-shadow: 0 10px 24px rgba(15, 76, 129, 0.06);
}

.tm-step h3 {
    margin: 0 0 10px;
    font-size: 17px;
    line-height: 1.35;
}

.tm-step p,
.tm-step li {
    margin: 0;
    color: #475569;
    line-height: 1.6;
}

.tm-step ul {
    margin: 10px 0 0 18px;
    padding: 0;
}

.tm-links {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 12px;
}

.tm-links a {
    text-decoration: none;
    border-radius: 999px;
    padding: 7px 11px;
    background: #edf4ff;
    color: #0f4c81;
    border: 1px solid #c9dcf5;
    font-size: 12px;
    font-weight: 600;
}

@media (max-width: 920px) {
    .tm-flow-hero {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 560px) {
    .tm-flow-metrics {
        grid-template-columns: 1fr;
    }
}

.tm-mini-shell {
    overflow-x: auto;
    padding-bottom: 6px;
}

.tm-mini-track {
    display: inline-flex;
    align-items: center;
    gap: 14px;
    min-width: 100%;
    padding: 4px 2px;
}

.tm-mini-step {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 168px;
    padding: 12px 16px;
    border-radius: 999px;
    text-decoration: none;
    background: linear-gradient(135deg, #fff7ed 0%, #eff6ff 100%);
    border: 1px solid #d7e3f1;
    color: #1e293b;
    font-size: 12px;
    font-weight: 700;
    box-shadow: 0 6px 18px rgba(15, 76, 129, 0.07);
}

.tm-mini-step:not(:last-child)::after {
    content: "";
    position: absolute;
    right: -14px;
    top: 50%;
    width: 14px;
    height: 2px;
    background: #94a3b8;
    transform: translateY(-50%);
}
